/** Lat/lng to map units (same projection as the outline). */
export function project(lat: number, lng: number): { x: number; y: number } {
  const l = Math.max(Math.min(lat, 83), -58);
  const m = Math.log(Math.tan(Math.PI / 4 + (l * Math.PI / 180) / 2));
  return { x: (lng + 180) / 360 * WORLD_W, y: (Y0 - m) * S };
}
